/* App.css */

.container {
  max-width: 1000px;
  margin: 40px auto;
  padding: 24px;
  background: var(--bg);
  border-radius: 12px;
  box-shadow: var(--shadow);
  border: 1px solid var(--border);
  text-align: left;
}

.header {
  margin-bottom: 32px;
  border-bottom: 1px solid var(--border);
  padding-bottom: 16px;
}

.header h1 {
  font-size: 32px;
  margin: 0 0 8px 0;
  color: var(--text-h);
}

.header p {
  color: var(--text);
  font-size: 16px;
  margin: 0;
}

.table-wrapper {
  overflow-x: auto;
  border: 1px solid var(--border);
  border-radius: 8px;
  background: var(--bg);
  margin-bottom: 24px;
}

.data-table {
  width: 100%;
  border-collapse: collapse;
  text-align: left;
  font-size: 15px;
}

.data-table th {
  background: var(--code-bg);
  color: var(--text-h);
  padding: 14px 16px;
  font-weight: 600;
  border-bottom: 1px solid var(--border);
  text-transform: uppercase;
  font-size: 12px;
  letter-spacing: 0.5px;
}

.data-table td {
  padding: 16px;
  border-bottom: 1px solid var(--border);
  color: var(--text);
  vertical-align: middle;
}

.data-table tr:last-child td {
  border-bottom: none;
}

.data-table tr:hover td {
  background: rgba(170, 59, 255, 0.02);
}

/* Badges */
.id-badge {
  font-family: var(--mono);
  background: var(--code-bg);
  color: var(--text-h);
  padding: 4px 8px;
  border-radius: 4px;
  font-size: 13px;
  font-weight: 500;
}

.role-badge {
  display: inline-flex;
  align-items: center;
  padding: 4px 10px;
  border-radius: 12px;
  font-size: 12px;
  font-weight: 600;
  text-transform: capitalize;
}

.role-badge.Admin {
  background: rgba(239, 68, 68, 0.1);
  color: rgb(239, 68, 68);
}

.role-badge.Editor {
  background: rgba(245, 158, 11, 0.1);
  color: rgb(245, 158, 11);
}

.role-badge.User {
  background: rgba(59, 130, 246, 0.1);
  color: rgb(59, 130, 246);
}

/* User Name & Email */
.user-name {
  font-weight: 500;
  color: var(--text-h);
}

.user-email {
  color: var(--text);
}

/* Inputs and Selects in Edit Mode */
.input-container {
  display: flex;
  flex-direction: column;
  gap: 4px;
}

.edit-input,
.edit-select {
  width: 100%;
  box-sizing: border-box;
  padding: 8px 12px;
  border: 1px solid var(--border);
  border-radius: 6px;
  background: var(--bg);
  color: var(--text-h);
  font-family: var(--sans);
  font-size: 14px;
  transition: all 0.2s ease;
}

.edit-input:focus,
.edit-select:focus {
  outline: none;
  border-color: var(--accent);
  box-shadow: 0 0 0 3px var(--accent-bg);
}

.edit-input.input-error,
.edit-select.input-error {
  border-color: #ef4444;
}

.edit-input.input-error:focus,
.edit-select.input-error:focus {
  box-shadow: 0 0 0 3px rgba(239, 68, 68, 0.15);
}

.error-text {
  color: #ef4444;
  font-size: 12px;
  font-weight: 500;
  margin-top: 2px;
}

/* Buttons */
.action-buttons {
  display: flex;
  gap: 8px;
}

.btn {
  font-family: var(--sans);
  font-size: 13px;
  font-weight: 600;
  padding: 6px 12px;
  border-radius: 6px;
  border: 1px solid transparent;
  cursor: pointer;
  transition: all 0.2s ease;
  display: inline-flex;
  align-items: center;
  justify-content: center;
}

.btn-edit {
  background: var(--accent-bg);
  color: var(--accent);
  border-color: transparent;
}

.btn-edit:hover:not(:disabled) {
  background: var(--accent);
  color: #fff;
}

.btn-edit:disabled {
  opacity: 0.5;
  cursor: not-allowed;
}

.btn-save {
  background: #10b981;
  color: white;
}

.btn-save:hover {
  background: #059669;
}

.btn-cancel {
  background: var(--code-bg);
  color: var(--text);
  border-color: var(--border);
}

.btn-cancel:hover {
  background: var(--border);
  color: var(--text-h);
}

/* Reset / Demo Info */
.demo-info {
  margin-top: 24px;
  padding: 16px;
  background: var(--code-bg);
  border-radius: 8px;
  border-left: 4px solid var(--accent);
  font-size: 14px;
}

.demo-info h3 {
  margin: 0 0 8px 0;
  color: var(--text-h);
  font-size: 16px;
}

.demo-info p {
  margin: 0;
  color: var(--text);
}

.validation-summary {
  background: rgba(239, 68, 68, 0.08);
  border: 1px solid rgba(239, 68, 68, 0.2);
  color: #ef4444;
  padding: 12px 16px;
  border-radius: 6px;
  margin-bottom: 20px;
  font-size: 14px;
}

.validation-summary ul {
  margin: 4px 0 0 0;
  padding-left: 20px;
}

import { useState, useMemo } from 'react'
import {
  useReactTable,
  getCoreRowModel,
  flexRender,
  ColumnDef,
} from '@tanstack/react-table'
import { useForm } from '@tanstack/react-form'
import './App.css'

interface User {
  id: string
  name: string
  email: string
  role: string
}

const initialUsers: User[] = [
  { id: '1', name: 'Alice Smith', email: 'alice@example.com', role: 'Admin' },
  { id: '2', name: 'Bob Jones', email: 'bob@example.com', role: 'User' },
  { id: '3', name: 'Charlie Brown', email: 'charlie@example.com', role: 'Editor' },
]

function App() {
  const [data, setData] = useState<User[]>(initialUsers)
  const [editingRowId, setEditingRowId] = useState<string | null>(null)
  const [validationErrors, setValidationErrors] = useState<string[]>([])

  // TanStack Form instance to manage inline edit state and validation
  const form = useForm<User>({
    defaultValues: {
      id: '',
      name: '',
      email: '',
      role: '',
    },
    onSubmit: async ({ value }) => {
      // Clear errors on successful submit
      setValidationErrors([])
      // Update data state with edited values
      setData((prev) =>
        prev.map((user) => (user.id === value.id ? value : user))
      )
      // Exit edit mode
      setEditingRowId(null)
    },
    onSubmitInvalid: ({ formApi }) => {
      // Collect errors to display a summary if validation fails
      const errorsList: string[] = []
      const state = formApi.state

      // Look through field-level errors
      Object.keys(state.values).forEach((key) => {
        const fieldMeta = formApi.getFieldMeta(key as keyof User)
        if (fieldMeta?.errors?.length) {
          errorsList.push(`${key.charAt(0).toUpperCase() + key.slice(1)}: ${fieldMeta.errors.join(', ')}`)
        }
      })
      setValidationErrors(errorsList)
    }
  })

  const handleStartEdit = (user: User) => {
    setEditingRowId(user.id)
    setValidationErrors([])
    // Reset form to the selected user's values
    form.reset(user)
  }

  const handleCancel = () => {
    setEditingRowId(null)
    setValidationErrors([])
    form.reset()
  }

  // TanStack Table columns definition
  const columns = useMemo<ColumnDef<User>[]>(
    () => [
      {
        accessorKey: 'id',
        header: 'ID',
        cell: (info) => <span className="id-badge">{info.getValue() as string}</span>,
      },
      {
        accessorKey: 'name',
        header: 'Name',
        cell: (info) => {
          const rowId = info.row.original.id
          const isEditing = editingRowId === rowId

          if (isEditing) {
            return (
              <form.Field
                name="name"
                validators={{
                  onChange: ({ value }) => {
                    if (!value || !value.trim()) {
                      return 'Name is required'
                    }
                    return undefined
                  },
                }}
              >
                {(field) => (
                  <div className="input-container">
                    <input
                      value={field.state.value}
                      onBlur={field.handleBlur}
                      onChange={(e) => field.handleChange(e.target.value)}
                      className={`edit-input ${
                        field.state.meta.errors.length ? 'input-error' : ''
                      }`}
                      placeholder="Name"
                    />
                    {field.state.meta.errors.length ? (
                      <span className="error-text">
                        {field.state.meta.errors.join(', ')}
                      </span>
                    ) : null}
                  </div>
                )}
              </form.Field>
            )
          }

          return <span className="user-name">{info.getValue() as string}</span>
        },
      },
      {
        accessorKey: 'email',
        header: 'Email',
        cell: (info) => {
          const rowId = info.row.original.id
          const isEditing = editingRowId === rowId

          if (isEditing) {
            return (
              <form.Field
                name="email"
                validators={{
                  onChange: ({ value }) => {
                    if (!value || !value.trim()) {
                      return 'Email is required'
                    }
                    const emailRegex = /^[^\s@]+@[^\s@]+\.[^\s@]+$/
                    if (!emailRegex.test(value)) {
                      return 'Invalid email format'
                    }
                    return undefined
                  },
                }}
              >
                {(field) => (
                  <div className="input-container">
                    <input
                      type="email"
                      value={field.state.value}
                      onBlur={field.handleBlur}
                      onChange={(e) => field.handleChange(e.target.value)}
                      className={`edit-input ${
                        field.state.meta.errors.length ? 'input-error' : ''
                      }`}
                      placeholder="Email"
                    />
                    {field.state.meta.errors.length ? (
                      <span className="error-text">
                        {field.state.meta.errors.join(', ')}
                      </span>
                    ) : null}
                  </div>
                )}
              </form.Field>
            )
          }

          return <span className="user-email">{info.getValue() as string}</span>
        },
      },
      {
        accessorKey: 'role',
        header: 'Role',
        cell: (info) => {
          const rowId = info.row.original.id
          const isEditing = editingRowId === rowId

          if (isEditing) {
            return (
              <form.Field
                name="role"
                validators={{
                  onChange: ({ value }) => {
                    if (!value || !value.trim()) {
                      return 'Role is required'
                    }
                    return undefined
                  },
                }}
              >
                {(field) => (
                  <div className="input-container">
                    <select
                      value={field.state.value}
                      onBlur={field.handleBlur}
                      onChange={(e) => field.handleChange(e.target.value)}
                      className={`edit-select ${
                        field.state.meta.errors.length ? 'input-error' : ''
                      }`}
                    >
                      <option value="">Select Role</option>
                      <option value="Admin">Admin</option>
                      <option value="User">User</option>
                      <option value="Editor">Editor</option>
                    </select>
                    {field.state.meta.errors.length ? (
                      <span className="error-text">
                        {field.state.meta.errors.join(', ')}
                      </span>
                    ) : null}
                  </div>
                )}
              </form.Field>
            )
          }

          const roleValue = info.getValue() as string
          return <span className={`role-badge ${roleValue}`}>{roleValue}</span>
        },
      },
      {
        id: 'actions',
        header: 'Actions',
        cell: (info) => {
          const rowId = info.row.original.id
          const isEditing = editingRowId === rowId

          if (isEditing) {
            return (
              <div className="action-buttons">
                <button
                  type="submit"
                  className="btn btn-save"
                  title="Save changes"
                >
                  Save
                </button>
                <button
                  type="button"
                  className="btn btn-cancel"
                  onClick={handleCancel}
                  title="Cancel editing"
                >
                  Cancel
                </button>
              </div>
            )
          }

          return (
            <div className="action-buttons">
              <button
                type="button"
                className="btn btn-edit"
                onClick={() => handleStartEdit(info.row.original)}
                disabled={editingRowId !== null}
                title="Edit this user"
              >
                Edit
              </button>
            </div>
          )
        },
      },
    ],
    [editingRowId, form]
  )

  const table = useReactTable({
    data,
    columns,
    getCoreRowModel: getCoreRowModel(),
  })

  return (
    <div className="container">
      <div className="header">
        <h1>User Directory</h1>
        <p>Manage user accounts and roles with inline editing capabilities.</p>
      </div>

      {validationErrors.length > 0 && (
        <div className="validation-summary">
          <strong>Please fix the following validation errors:</strong>
          <ul>
            {validationErrors.map((err, idx) => (
              <li key={idx}>{err}</li>
            ))}
          </ul>
        </div>
      )}

      <form
        onSubmit={(e) => {
          e.preventDefault()
          e.stopPropagation()
          form.handleSubmit()
        }}
      >
        <div className="table-wrapper">
          <table className="data-table">
            <thead>
              {table.getHeaderGroups().map((headerGroup) => (
                <tr key={headerGroup.id}>
                  {headerGroup.headers.map((header) => (
                    <th key={header.id}>
                      {header.isPlaceholder
                        ? null
                        : flexRender(
                            header.column.columnDef.header,
                            header.getContext()
                          )}
                    </th>
                  ))}
                </tr>
              ))}
            </thead>
            <tbody>
              {table.getRowModel().rows.map((row) => (
                <tr key={row.id}>
                  {row.getVisibleCells().map((cell) => (
                    <td key={cell.id}>
                      {flexRender(
                        cell.column.columnDef.cell,
                        cell.getContext()
                      )}
                    </td>
                  ))}
                </tr>
              ))}
            </tbody>
          </table>
        </div>
      </form>

      <div className="demo-info">
        <h3>How it works</h3>
        <p>
          This table uses <strong>TanStack Table</strong> to manage columns, rows, and cellular rendering.
          When you click "Edit", the row switches into edit mode, and <strong>TanStack Form</strong> takes over
          the state of that row. It performs real-time validation (e.g. name is required, email must be valid)
          and prevents saving unless all criteria are met.
        </p>
      </div>
    </div>
  )
}

export default App

